def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
    - Multiplos de 3 son 'Fizz'
    - Multiplos de 5 son 'Buzz'
    - Multiplos de ambos (15, 30, ...) son 'FizzBuzz'
    - Los demás números se convierten a string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales y devuelve
    la tupla (elemento, longitud). Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_elemento = lista[0]
    racha_actual = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            racha_actual += 1
        else:
            if racha_actual > max_racha:
                max_racha = racha_actual
                max_elemento = lista[i - 1]
            racha_actual = 1

    # Verificar el último elemento
    if racha_actual > max_racha:
        max_racha = racha_actual
        max_elemento = lista[-1]

    return (max_elemento, max_racha)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    primos = [2]
    i = 3
    while i <= n:
        if all(n % j != 0 for j in range(2, i)):
            primos.append(i)
        i += 2
    return primos

def mcd(a, b):
    """
    Devuelve el máximo común divisor de dos enteros no negativos.
    El mcd de un número con 0 es ese número.
    """
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def comprimir(s: str) -> str:
    """Aplica codificación por repeticiones.

    'aaabb' se convierte en 'a3b2'.
    Si la versión comprimida es más corta que la original,
    se devuelve la versión comprimida.
    Si no es más corta, se devuelve la original sin cambios.
    """
    if not s:
        return s

    # Contar repeticiones de cada carácter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir la versión comprimida
    compressed = ""
    for char, count in counts.items():
        compressed += char * count

    # Verificar si es más corta
    if len(compressed) < len(s):
        return compressed
    else:
        return s

def balanceado(s: str) -> bool:
    """
    Verifica si los paréntesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False si no lo son.
    """
    if not s:
        return True

    open_brackets = []
    for char in s:
        if char in '({[':
            open_brackets.append(char)
        elif char in ')}]':
            if not open_brackets:
                return False
            open_brackets.pop()
        else:
            open_brackets.append(char)

    return len(open_brackets) == 0

def suma_digitos(n: int) -> int:
    """Suma los dígitos de un número y repite el proceso hasta quedarse con un solo dígito."""
    while len(str(n)) > 1:
        n = sum(int(digit) for digit in str(n))
    return n


