def en_lotes(lista, tamano):
    """Partir una lista en sublistas de un tamaño dado. El último lote puede ser más chico."""
    if not lista:
        return []
    return [lista[i:i + tamano] for i in range(0, len(lista), tamano)]

def balanceado(s: str) -> bool:
    """
    Verifica si los paréntesis, corchetes y llaves del string están bien
    balanceados y anidados. Los demás caracteres se ignoran.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False en caso contrario.
    """
    open_brackets = {'(', '[', '{'}
    close_brackets = {')', ']', '}'}
    stack = []

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack:
                return False
            top = stack.pop()
            if top != char:
                return False

    return len(stack) == 0

def anidar(plano: dict) -> dict:
    """
    Convierte un diccionario de claves con puntos en un diccionario anidado.

    Ejemplo: {'a.b': 1} -> {'a': {'b': 1}}

    Args:
        plano: Un diccionario donde las claves son strings con puntos '.' separados.

    Returns:
        Un diccionario anidado con las claves separadas por puntos.
    """
    result = {}
    for key, value in plano.items():
        parts = key.split('.')
        current = result
        for part in parts:
            if part not in current:
                current[part] = {}
            current = current[part]
        current[parts[-1]] = value
    return result

def comprimir(s: str) -> str:
    """Aplica run-length encoding a una string.

    Caracteres que aparecen una sola vez se representan como 'c1'.
    String vacio devuelve string vacio.
    """
    if not s:
        return ""

    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    result = []
    for char, count in counts.items():
        if count == 1:
            result.append(f"{char}1")
        else:
            result.append(f"{char}{count}")

    return "".join(result)

def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a texto legible usando multiplos de 1024 y las unidades B, KB, MB, GB."""
    if n == 0:
        return "0 B"
    if n < 1024:
        return f"{n} B"
    if n < 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    if n < 1024 * 1024 * 1024:
        return f"{n / (1024 * 1024):.1f} MB"
    return f"{n / (1024 * 1024 * 1024):.1f} GB"

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

