def con_reintentos(fn, veces):
    """
    Ejecuta fn() y, si lanza una excepcion, la reintenta hasta 'veces' intentos en total.
    Si todos fallan, vuelve a lanzar la ultima excepcion.
    Devuelve el resultado si alguno funciona.

    Args:
        fn: Función que puede lanzar excepciones.
        veces: Número máximo de intentos.

    Returns:
        El resultado de la primera ejecución exitosa de fn().
    """
    for i in range(veces):
        try:
            return fn()
        except Exception as e:
            if i == veces - 1:
                raise e  # Si todos fallan, vuelve a lanzar la última excepcion
            # Si falló en un intento anterior, continuamos intentando
            # (el except no se ejecuta si la función no lanza la misma excepción)
    return None  # Si todos fallaron, no se devolvió nada
